//
//  E2EEParityTests.swift
//  Foresight Camera Client — cross-platform E2EE parity gate.
//
//  The vector values are FROZEN, hand-copied from
//  `shared/test-vectors/e2ee-parity.json` (generated by
//  shared/ts/scripts/generate-e2ee-vector.mjs); edit only to re-sync with that
//  file. They prove swift-sodium derives byte-identical results to
//  libsodium-wrappers-sumo (web), sodium-native (recorder), and the iOS viewer —
//  a mismatch on ANY of them is the "silent black video" failure.
//
//  Requires swift-sodium + the iOS simulator; run on a Mac.
//

import Foundation
import Sodium
import XCTest
@testable import ForesightCameraClient

final class E2EEParityTests: XCTestCase {
    // MARK: Frozen vector (shared/test-vectors/e2ee-parity.json)

    private let password = "correct horse battery staple — foresight M0"
    private let saltB64 = "wfkgIOHuV4vUeKvR9g4Pqw=="
    private let opsLimit = 3
    private let memLimit = 67_108_864
    private let vaultKeyB64 = "S2JpU9Z88Dh0G7UxArcyHg5L+0ijpF+rc+MDRO+kTuY="
    private let publicKeyB64 = "BnTzuuX2LXGptq6HuBIDNiGi+gUroXCOiXeSwLd8yAg="
    private let privateKeyB64 = "HxiL9OB2G3kVAJb4rbKwM2+e1OcJ4tZTzF7KzoaMoA0="
    private let nonceB64 = "kSGjM3kcsDev6pYpvPB1DxGW/AYFyhXR"
    private let wrappedPrivateKeyB64 = "TZTA2fVfqzJHLns1ME/tepnhW91CcDuvcejWdHyzp01Lx+1V+e+4hZWSCRaVXeZg"
    private let hmkB64 = "pD+rpYrZqguuD2s4wCCNQt8EdvRqByCLa0jwD+/bbqE="
    private let livekitSetKeyString = "pD+rpYrZqguuD2s4wCCNQt8EdvRqByCLa0jwD+/bbqE="
    private let sealedHmkB64 = "WxXa71hPfQcjlJejQgHgfxJPnXKRr2crNAOg9gKXyjxQUDk5biabNjSwZEt3FSTAepLKDHa/TVG8A7ZFhuuu4r9vVPZD9hXlHYDogbvB/zA="

    private let sodium = Sodium()

    private func bytes(_ b64: String) throws -> [UInt8] {
        [UInt8](try XCTUnwrap(Data(base64Encoded: b64), "invalid base64: \(b64)"))
    }

    // MARK: 1) Argon2id(password, salt) == vaultKey
    //
    // The one token that could not be verified on Windows is the algorithm enum
    // case: swift-sodium spells it `.Argon2ID13` (libsodium ALG_ARGON2ID13). If a
    // future swift-sodium pin renames it (e.g. `.Argon2id13`), update it here.
    func testArgon2idDerivesVaultKey() throws {
        let derived = try XCTUnwrap(
            sodium.pwHash.hash(outputLength: 32,   // crypto_secretbox key = 32 B
                               passwd: Array(password.utf8),
                               salt: try bytes(saltB64),
                               opsLimit: opsLimit,
                               memLimit: memLimit,
                               alg: .Argon2ID13),
            "Argon2id returned nil")
        XCTAssertEqual(derived, try bytes(vaultKeyB64))
    }

    // MARK: 2) crypto_secretbox_open(wrappedPrivateKey, nonce, vaultKey) == privateKey
    func testSecretboxUnwrapsPrivateKey() throws {
        let opened = try XCTUnwrap(
            sodium.secretBox.open(authenticatedCipherText: try bytes(wrappedPrivateKeyB64),
                                  secretKey: try bytes(vaultKeyB64),
                                  nonce: try bytes(nonceB64)),
            "secretbox open returned nil")
        XCTAssertEqual(opened, try bytes(privateKeyB64))
    }

    // MARK: 3) crypto_box_seal_open(sealedHmk) == hmk
    func testSealedBoxUnsealsHmk() throws {
        let opened = try XCTUnwrap(
            sodium.box.open(anonymousCipherText: try bytes(sealedHmkB64),
                            recipientPublicKey: try bytes(publicKeyB64),
                            recipientSecretKey: try bytes(privateKeyB64)),
            "sealed box open returned nil")
        XCTAssertEqual(opened, try bytes(hmkB64))
        XCTAssertEqual(try bytes(sealedHmkB64).count, ForesightE2EE.sealedHmkBytes)   // 80
    }

    // MARK: 4) base64(hmk) is the exact string handed to LiveKit setKey
    func testHmkBase64IsLivekitSetKeyString() throws {
        let hmk = try bytes(hmkB64)
        XCTAssertEqual(hmk.count, ForesightE2EE.hmkBytes)   // 32
        XCTAssertEqual(Data(hmk).base64EncodedString(), livekitSetKeyString)
    }

    // MARK: App constants match the frozen vector's LiveKit block
    func testForesightE2EEConstantsMatchVector() {
        XCTAssertEqual(ForesightE2EE.keySize, 128)
        XCTAssertEqual(ForesightE2EE.encryptionType, "gcm")
        XCTAssertEqual(ForesightE2EE.ratchetSalt, "LKFrameEncryptionKey")
        XCTAssertEqual(ForesightE2EE.ratchetWindowSize, 0)
        XCTAssertEqual(ForesightE2EE.keyIndex, 0)
        XCTAssertEqual(ForesightE2EE.argon2idOpslimit, opsLimit)
        XCTAssertEqual(ForesightE2EE.argon2idMemlimit, memLimit)
        XCTAssertEqual(ForesightE2EE.sealedHmkBytes, 80)
        XCTAssertEqual(ForesightE2EE.hmkBytes, 32)
    }
}
